<script setup>import {ref} from 'vue';const p=defineProps({masterJobs:Array}),emit=defineEmits(['save','delete']),editing=ref(null),form=ref({code:'',name:'',points:1,active:true});function nw(){editing.value='new';form.value={code:'',name:'',points:1,active:true}}function edit(m){editing.value=m.id;form.value={...m}}function save(){if(!form.value.code||!form.value.name)return;emit('save',{...form.value,points:Number(form.value.points)});editing.value=null}</script><template><section class="page-head"><div><span class="eyebrow">MASTER DATA</span><h1>Jenis Pekerjaan</h1><p>Kelola bobot poin yang digunakan kalkulator.</p></div><button class="btn-primary" @click="nw">＋ Tambah Jenis</button></section><div class="panel"><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Jenis pekerjaan</th><th>Bobot poin</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="m in masterJobs" :key="m.id"><td><code>{{m.code}}</code></td><td><b>{{m.name}}</b></td><td><span class="point-pill">{{m.points}} poin</span></td><td><span :class="['status-pill',m.active?'on':'off']">{{m.active?'Aktif':'Nonaktif'}}</span></td><td><button class="text-btn" @click="edit(m)">Edit</button><button class="text-btn danger" @click="emit('delete',m.id)">Hapus</button></td></tr></tbody></table></div></div><div v-if="editing!==null" class="modal-backdrop" @click.self="editing=null"><div class="modal"><div class="panel-head"><div><span class="eyebrow">MASTER</span><h2>{{editing==='new'?'Tambah':'Edit'}} Pekerjaan</h2></div><button class="close" @click="editing=null">×</button></div><div class="form-grid"><label>Kode<input v-model="form.code"></label><label>Nama pekerjaan<input v-model="form.name"></label><label>Bobot poin<input v-model.number="form.points" type="number" min="0"></label><label class="check"><input v-model="form.active" type="checkbox"> Aktif digunakan</label></div><div class="modal-actions"><button class="btn-secondary" @click="editing=null">Batal</button><button class="btn-primary" @click="save">Simpan</button></div></div></div></template>